// Short descriptions for the place pop-up: what it is, why it is famous, when to go.
export const PLACE_INFO = {"1":{"what":"Old riverside quarter of Chinatown, full of shophouses and workshops.","why":"Street art and car-part workshops, the Chinese courtyard mansion So Heng Tai, and Hong Sieng Kong café."},"2":{"what":"Narrow Chinatown lane of bars in century-old shophouses.","why":"Gin at Teens of Thailand, foraged-ingredient cocktails at Asia Today, Thai music at Tep Bar.","when":"Later in the evening; the bars here open late."},"3":{"what":"Chinatown's main road, lined with gold shops and old neon signs.","why":"One of Asia's great street-food strips: seafood, noodles, buns and Chinese desserts under the neon.","when":"After dark, once the stalls set up along the main road."},"4":{"what":"Royal temple complex just south of the Grand Palace.","why":"Home of the 46 m gilded Reclining Buddha and Thailand's best-known traditional massage school.","when":"Early morning, before the tour groups arrive."},"5":{"what":"Riverside hotel dating to 1876, a Bangkok institution.","why":"Live jazz at the Bamboo Bar, open since 1953, and afternoon tea in the colonial Authors' Lounge.","when":"Afternoon for tea, evening for jazz; smart dress expected."},"6":{"what":"Upscale Sukhumvit district around Soi 55.","why":"The Commons' open-air food hall plus a dense strip of cocktail bars, Japanese restaurants and cafés.","when":"Evenings, when the bars along Soi 55 fill up."},"7":{"what":"Riverside Temple of Dawn on the Thonburi bank.","why":"Its porcelain-studded central prang is one of Bangkok's defining sights, best framed from across the river.","when":"Sunset, viewed from the Tha Tien side of the river."},"8":{"what":"Vast weekend market with thousands of stalls in northern Bangkok.","why":"Clothes, crafts, antiques, plants and street food in a maze of covered lanes; easy to lose a day.","when":"Saturdays and Sundays; arrive in the morning before the heat."},"9":{"what":"Big open-air night market off Srinakarin Road, behind Seacon Square.","why":"Known for vintage collectibles, classic cars and retro bars alongside rows of food stalls.","when":"Weekend evenings, once the stalls are fully set up after dark."},"10":{"what":"Three-storey shophouse bar on Soi Suan Phlu 1.","why":"Dim, art-filled and eclectic, with some of the city's most serious live jazz.","when":"Wednesday nights for its regular jazz."},"11":{"what":"Long-running live music pub near Victory Monument.","why":"Jazz, blues and funk bands play nightly in one of Bangkok's best-loved music venues.","when":"Later in the evening; arrive early on weekends to get a seat."},"12":{"what":"Commuter boat service on the Chao Phraya River.","why":"A cheap ride upriver past Wat Arun, with stops for Chinatown and the Grand Palace.","when":"Daytime; services wind down in the early evening."},"13":{"what":"Observation deck atop the pixel-patterned King Power Mahanakhon tower.","why":"A glass floor 310 m above the street, plus a rooftop bar with 360-degree views.","when":"Around sunset on a clear day."},"14":{"what":"Huge luxury mall on the Thonburi bank of the river.","why":"SookSiam, an indoor food hall styled on a floating market, plus wide river views over to Bang Rak."},"15":{"what":"Former royal palace complex and Thailand's most sacred temple.","why":"Wat Phra Kaew enshrines the revered Emerald Buddha amid glittering halls, spires and murals.","when":"Right at opening, before the heat and tour buses; cover shoulders and knees."},"16":{"what":"Short neon-lit lane of go-go bars near Asok.","why":"One of Bangkok's best-known red-light strips, photographed for its wall-to-wall neon; adults only."},"17":{"what":"Three-storey complex of go-go bars on Sukhumvit Soi 4.","why":"Billed as the world's largest adult entertainment complex; a red-light venue for adults only."},"18":{"what":"Wetland park on former tobacco factory land beside the convention centre.","why":"A 1.6 km elevated skywalk loops over reed beds and ponds, with skyline views.","when":"Early morning or late afternoon, when it is cooler."},"19":{"what":"Bangkok's best-known central park, opposite Silom.","why":"Monitor lizards roam the lakes, paddle boats are for hire and joggers circle the paths.","when":"Early morning or late afternoon; everything stops for the anthem at 6 pm."},"20":{"what":"Museum in a cluster of traditional teak houses beside a canal.","why":"Former home of the American who revived Thai silk, then vanished in 1967; filled with Asian art."},"21":{"what":"Old warehouses on Charoen Krung Soi 30, turned into a creative hub.","why":"Design shops, studios and cafés on a creative strip that also takes in TCDC and small galleries."},"22":{"what":"Historic riverside trading street on Chinatown's southern edge.","why":"Spice and dried-goods wholesalers share old shophouses with newer cafés, galleries and street art."},"23":{"what":"Big night market, now beside Thailand Cultural Centre MRT on Ratchada.","why":"Rows of food stalls known for towering spicy pork-bone leng saep, plus bars and clothes stalls.","when":"Evenings; busiest after dark at weekends."},"24":{"what":"Laid-back residential neighbourhood around BTS Ari.","why":"Leafy lanes of independent cafés, brunch spots and street-food stalls, popular with young Bangkokians."},"25":{"what":"Mid-1800s Chinese pier and warehouse complex on the Thonburi bank.","why":"Known for its Mazu shrine and courtyard buildings; the site is being redeveloped, so check access first."},"26":{"what":"Canal-side Thonburi temple, home of Bangkok's Big Buddha.","why":"Its 69 m Buddha dominates the skyline; the stupa's top floor hides a green glass chedi."},"27":{"what":"Charcoal-wok street-food restaurant on Maha Chai Road in the old town.","why":"Chef Jay Fai, cooking in her trademark ski goggles, won a Michelin star for her crab omelette.","when":"Reserve well ahead, or queue early for the walk-in list."},"28":{"what":"Food street running beside Chulalongkorn University.","why":"A dense strip of noodle, seafood and dessert shops, led by Jeh O Chula's tom yum Mama noodles.","when":"Evenings and late at night, when queues build at the famous shops."},"29":{"what":"Upmarket fresh market across the road from Chatuchak.","why":"Prized for top-grade fruit, curry pastes and ready-made dishes; often ranked among the world's best fresh markets.","when":"Mornings, ideally combined with Chatuchak at the weekend."},"30":{"what":"Bangkok's main wholesale flower market, near Memorial Bridge.","why":"Mountains of orchids, roses, jasmine and marigold garlands, traded around the clock.","when":"Late night to early morning, when fresh flowers are unloaded."},"31":{"what":"Two lanes between Silom and Surawong known for go-go bars.","why":"Bangkok's original nightlife strip, notorious since the Vietnam War era; its evening market sells souvenirs and knock-offs."},"32":{"what":"Three-storey speakeasy-style cocktail bar on Thonglor.","why":"Hidden behind a wooden door marked only by a small rabbit, it is known for inventive cocktails."},"33":{"what":"Hilltop chedi at Wat Saket, on the edge of the old town.","why":"A spiral climb of about 300 steps leads to a gold chedi with sweeping old-town views.","when":"Late afternoon for the view; temple fair runs around Loy Krathong in November."},"34":{"what":"Large green peninsula in a loop of the Chao Phraya.","why":"Plantations, mangroves and raised bike paths, a short boat ride from Khlong Toei.","when":"Weekends, when the Bang Nam Phueng floating market is open."},"35":{"what":"Busy street market by Siriraj Hospital and Wang Lang Pier.","why":"Locals come for cheap Thai snacks, sweets and curries; the Siriraj medical museums are next door."},"36":{"what":"Sukhumvit Soi 63 neighbourhood, next door to Thonglor.","why":"Wattana Panich's beef broth, kept simmering for decades, plus vintage shops, cafés and bars."},"37":{"what":"Bangkok's oldest Muay Thai stadium, on Ratchadamnoen Nok Avenue.","why":"Home of top-level Thai boxing since 1945, with fights on most nights of the week.","when":"Saturday nights for the headline RWS card; check schedules first."},"38":{"what":"Backpacker street in Banglamphu, with quieter Soi Rambuttri nearby.","why":"Bars, street food and cheap guesthouses in a late-night party strip; Rambuttri is calmer and leafier.","when":"Evenings; during Songkran in mid-April it becomes a giant water fight."},"39":{"what":"One of Southeast Asia's biggest malls, at the Ratchaprasong intersection.","why":"Hundreds of shops and restaurants, plus a front plaza that hosts a major New Year countdown."},"40":{"what":"Three malls clustered around BTS Phrom Phong.","why":"Luxury labels at Emporium, EmQuartier's spiral of restaurants, and EmSphere's IKEA and concert hall."},"41":{"what":"Obelisk marking the Franco-Thai war, on a huge roundabout.","why":"Its canal-side Boat Noodle Alley serves rich noodles in small bowls, so diners order several and stack them."},"42":{"what":"Public contemporary art centre opposite MBK at Pathumwan.","why":"Free, changing exhibitions on floors linked by a white spiral ramp, plus small galleries, shops and cafes.","when":"Any day except Monday, when it is closed."},"43":{"what":"Private museum of modern Thai art in northern Bangkok.","why":"Five floors of Thai painting and sculpture, with major works by Thawan Duchanee and Chalermchai Kositpipat.","when":"Closed Mondays; it is out of the centre, so allow half a day."},"44":{"what":"Rum-focused tropical cocktail bar on a Charoen Krung side street.","why":"A regular on the Asia's 50 Best Bars list, mixing tiki and Caribbean drinks with Southeast Asian flavours."},"45":{"what":"Open-air bar on the 63rd floor of Lebua's State Tower.","why":"Sweeping Chao Phraya views from a glowing ledge bar made famous by The Hangover Part II.","when":"Sunset; arrive early and skip shorts and flip-flops for the dress code."},"46":{"what":"Open-air rooftop restaurant and bar atop Banyan Tree Bangkok on Sathorn.","why":"Dinner or drinks 61 floors up, with wide views over Lumphini Park and the Sathorn skyline.","when":"Around sunset; it is fully open-air, so it can close in heavy rain."},"47":{"what":"Three-level rooftop bar atop the Bangkok Marriott Sukhumvit in Thong Lo.","why":"Its top-floor circular bar offers a full 360-degree panorama, with few nearby towers in the way.","when":"Sunset, then stay as the city lights come on."},"48":{"what":"Short Sukhumvit side street near BTS Nana, full of bars and clubs.","why":"Easy bar-hopping, from cocktail lounges and rooftop terraces to big late-night clubs, all a short walk apart.","when":"Late on Friday and Saturday nights, when the clubs fill up."},"49":{"what":"Siam's open-air shopping grid plus two linked fashion and design malls.","why":"Siam Square's lanes draw students and indie labels; Siam Center and Siam Discovery spotlight Thai and global design."},"50":{"what":"Flagship luxury mall directly linked to BTS Siam.","why":"Designer brands, a basement aquarium, and Gourmet Market, a top stop for Thai snacks and food gifts."},"51":{"what":"Eight-floor mall by BTS National Stadium, packed with small stalls.","why":"Bangkok's go-to for phones, accessories, repairs and budget clothing, where polite haggling is normal."},"52":{"what":"Mall on Rama IV Road beside Chulalongkorn University and MRT Sam Yan.","why":"Its 24-hour zone includes the free Samyan Co-op workspace, popular with students and laptop workers."},"53":{"what":"Narrow Chinatown wholesale lane, also known as Soi Wanit 1.","why":"One of Bangkok's oldest trading streets, crammed with toys, beads, fabrics and accessories sold in bulk.","when":"Mornings, before the lane gets shoulder-to-shoulder with carts and shoppers."},"54":{"what":"Bangkok's Little India, beside Chinatown near MRT Sam Yot.","why":"Bolts of fabric and saris, Indian sweet shops and curry houses, and a large Sikh gurdwara."},"55":{"what":"Old Catholic riverside community in Thonburi with Portuguese roots.","why":"Santa Cruz Church, quiet old lanes and khanom farang, Portuguese-influenced cakes still baked by local families."},"56":{"what":"Riverside street in Banglamphu, a short walk from Khao San Road.","why":"The whitewashed Phra Sumen Fort, a breezy riverside park, and relaxed cafes, bars and live-music spots.","when":"Late afternoon, for sunset over the river at Santichaiprakan Park."},"57":{"what":"Gilded Brahma shrine on a busy corner beside the Grand Hyatt Erawan.","why":"Locals pray for luck here all day and hire classical dancers to give thanks when wishes come true."},"58":{"what":"New mixed-use district on Rama IV Road, opened in 2024.","why":"Malls, hotels, offices and landscaped plazas across from Lumphini Park, linked underground to MRT Lumphini."},"59":{"what":"Upscale mall on Ploenchit Road, topped by the Park Hyatt.","why":"Its sixth-floor Open House mixes an art bookshop, reading nooks, co-working seats and restaurants."},"60":{"what":"Airport-themed mall at the BTS Asok and MRT Sukhumvit interchange.","why":"Playful floors themed on Tokyo, London, Istanbul and more, plus Pier 21, a famously good-value food court."},"61":{"what":"Night bazaar in old riverside warehouses on Charoen Krung Road.","why":"Souvenir stalls, riverside restaurants and a giant Ferris wheel on the former docks of a Danish trading firm.","when":"Evenings; arrive by the shuttle boat from Sathorn Pier."},"62":{"what":"Temple beside Chinatown's gateway arch, near MRT Hua Lamphong.","why":"Its 5.5-tonne solid-gold Buddha lay hidden under plaster until the coating cracked in 1955."},"63":{"what":"Two short lanes off Silom Road at the heart of gay Bangkok.","why":"Soi 4 has bars with street-side seating for people-watching; Soi 2 is home to the dance clubs.","when":"Late evening, especially weekends; carry photo ID for the Soi 2 clubs."},"64":{"what":"Bangkok's biggest fresh market, on Rama IV Road near the port.","why":"A sprawling, gritty look at how the city eats, from live seafood and butchers to mountains of fruit.","when":"Early morning, when it is coolest and trading is busiest; wear closed shoes."},"65":{"what":"Century-old market among wooden shophouses near Government House.","why":"Known for traditional Thai sweets and snacks, many made by the same families for generations.","when":"Morning to lunchtime; the most popular sweets sell out early."},"66":{"what":"Weekend floating market on a Thonburi canal, beside the district office.","why":"River prawns and fish grilled on boats and eaten on floating pontoons, plus canal boat tours.","when":"Saturdays, Sundays and public holidays, from late morning to lunch."},"67":{"what":"Weekend canal-side food market in leafy Taling Chan.","why":"Locals graze on regional dishes and Thai sweets, while boats tour the surrounding canals and gardens.","when":"Saturdays and Sundays; arrive early to beat the lunchtime crowds and traffic."},"68":{"what":"Creative park and market in Thonburi, built largely from recycled materials.","why":"Its centrepiece is a full-size retired airliner, surrounded by quirky art, shops, bars and eateries.","when":"Late afternoon into evening; check it is open before heading out."},"69":{"what":"Multi-storey indoor vintage and secondhand mall near Chatuchak.","why":"Air-conditioned floors of vintage clothing, antique furniture, vinyl, cameras and collectibles, a cool break from Chatuchak."},"70":{"what":"Nightlife strip on Royal City Avenue, off Rama IX Road.","why":"Big clubs and live-music bars line a single street, drawing a young, mostly Thai crowd.","when":"Weekend nights after about 11 pm; door staff check photo ID."},"71":{"what":"Pad thai shop near the Golden Mount, running since 1966.","why":"Famous for pad thai wrapped in a thin omelette, washed down with freshly squeezed orange juice.","when":"Expect queues at dinner; mid-afternoon is usually quicker."},"72":{"what":"Tasting-menu restaurant in a restored 120-year-old Chinatown pharmacy.","why":"Chef Pam's progressive Thai-Chinese cooking earned a Michelin star; she was named World's Best Female Chef 2025.","when":"Book well ahead; tables fill up weeks in advance."},"73":{"what":"Original branch of an Isan restaurant group, on Sala Daeng Road.","why":"Unapologetically spicy som tam pounded to order, with larb, grilled meats and sticky rice from the northeast."},"74":{"what":"Thai restaurant cooking the owner's grandmother's recipes from Trat and Khon Kaen.","why":"Home-style dishes like pork stewed with cha muang leaves; the Tha Tien branch looks across to Wat Arun."},"75":{"what":"Fast commuter boats on Khlong Saen Saep, with Pratunam as the hub.","why":"A quick, splashy ride that skips traffic, with stops near the Golden Mount, Jim Thompson House and Siam.","when":"Avoid weekday rush hours, when boats are packed with commuters."},"76":{"what":"Quiet canal-side community of old wooden houses in Thonburi.","why":"Baan Silapin, an artists' house in an old wooden home, stages traditional Thai puppet shows beside the canal.","when":"Early afternoon for the 2 pm puppet show, held daily except Wednesday."},"77":{"what":"Vast open-air park of replica Thai temples and palaces, Samut Prakan.","why":"More than 100 landmarks from across Thailand, some full-size, spread over landscaped grounds best explored by bike.","when":"Go early or late afternoon; the grounds are huge and hot."},"78":{"what":"Museum inside a giant bronze three-headed elephant in Samut Prakan.","why":"Climb inside to an ornate hall under a domed stained-glass ceiling; built by the Ancient City's founder."},"79":{"what":"Medical museums at Siriraj, Thailand's oldest hospital, in Thonburi.","why":"Preserved organs, skeletons and forensic case exhibits from a teaching collection nicknamed the Museum of Death.","when":"Any day except Tuesday, when it is closed."},"80":{"what":"Royal temple clad in Italian Carrara marble, built under King Rama V.","why":"Graceful blend of Thai and European design, pictured on the five-baht coin, with a cloister of Buddha images.","when":"Early morning, when monks line up outside to receive alms."},"81":{"what":"Royal temple facing Sao Chingcha, the towering red Giant Swing.","why":"Fine murals, a 14th-century Sukhothai bronze Buddha, and the swing once used in Brahmin ceremonies."},"82":{"what":"Tiered metal castle at Wat Ratchanatdaram, crowned with 37 spires.","why":"The only surviving loha prasat in the world; climb inside for views towards the Golden Mount."},"83":{"what":"Chinatown's largest Chinese Buddhist temple, just off Charoen Krung Road.","why":"Incense-filled halls of gilded deities, busy with worshippers making offerings and asking for good fortune.","when":"Chinese New Year and the autumn vegetarian festival are the liveliest times."},"84":{"what":"Bangkok's main Hindu temple, built by Tamil migrants in 1879 on Silom.","why":"Its colourful tower of carved deities stands out on Silom, and people of many faiths pray here.","when":"Navaratri, around October, brings a spectacular street procession."},"85":{"what":"Bangkok's grand old railway terminus, opened in 1916.","why":"Arched Italian-style hall and stained glass; long-distance trains moved to Krung Thep Aphiwat in 2023."},"86":{"what":"Bangkok's main international airport, east of the city.","why":"Thailand's busiest gateway, linked to downtown by the Airport Rail Link to Phaya Thai."},"87":{"what":"Bangkok's wholesale clothing district, anchored by Platinum Fashion Mall.","why":"Floor after floor of small stalls selling clothes and accessories, often cheaper when you buy several."},"88":{"what":"Tiny shophouse blues bar on Samsen Road, near Khao San.","why":"Live blues every night in a cosy, vinyl-lined room that spills out onto the pavement.","when":"Evenings; weeknights are calmer, weekends are standing room only."},"89":{"what":"Lavish Chinese-themed nightclub on Sukhumvit Soi 45 by designer Ashley Sutton.","why":"Red lanterns, wrought iron and hidden nooks, with dancers and burlesque acts between house DJ sets.","when":"Late at night, when the shows and DJs are in full swing."},"90":{"what":"Jungle-themed rooftop bar atop the T-One building near Thong Lo.","why":"Famous for its glowing, jellyfish-like LED tree and tiki-style cocktails high above Sukhumvit.","when":"Sunset; arrive early, as queues build on weekends."},"91":{"what":"Old market district in Thonburi around Talat Phlu station.","why":"Named after the betel leaves once traded here, it is now loved for Chinese-Thai snacks and noodles."},"92":{"what":"Former riverside market by the Khlong San ferry pier, Thonburi.","why":"Long known for cheap clothes and street food; the old market closed around 2021 for redevelopment."},"93":{"what":"Car-free river island in Nonthaburi, home to a Mon pottery community.","why":"Mon terracotta workshops, a leaning riverside chedi and quiet lanes that are easy to walk or cycle.","when":"Weekends, when the market lanes and food stalls are open."},"94":{"what":"Cable-stayed bridge over the Chao Phraya with a single inverted-Y pylon.","why":"One of the world's largest asymmetric cable-stayed bridges and a striking riverside landmark.","when":"After dark, when it is lit; Santichaiprakan Park has good views."},"95":{"what":"Garden walkway on an abandoned elevated rail bridge across the Chao Phraya.","why":"Thailand's first park over a river, with open views up and down the water.","when":"Late afternoon to sunset, when it is cooler."},"96":{"what":"Thai spa chain with several large branches across Bangkok.","why":"Popular for skilled traditional Thai massage at fair prices in calm, spotless villa-style surroundings.","when":"Book ahead for evenings and weekends."},"97":{"what":"Unfinished riverside skyscraper near Saphan Taksin, known as the ghost tower.","why":"Construction stopped in the 1997 Asian financial crisis; entry is banned, so admire it from outside."},"98":{"what":"Monument in a roundabout on Ratchadamnoen Klang Avenue.","why":"Built in 1939 to commemorate the 1932 revolution; a rallying point for Thai protest movements."},"99":{"what":"Boathouse museum on Khlong Bangkok Noi housing royal ceremonial barges.","why":"Home of Suphannahong, the gilded swan-prowed royal barge carved from a single teak trunk."},"100":{"what":"City park beside the Emporium and EmSphere at BTS Phrom Phong.","why":"Lake, jogging track and modern sculptures; opened in 1992 for Queen Sirikit's 60th birthday."},"101":{"what":"Bangkok's original international airport, now the low-cost airline hub.","why":"Opened in 1914, it is one of Asia's oldest airports, with a golf course between its runways."},"102":{"what":"Historic university campus on the riverside beside Sanam Luang.","why":"Founded in 1934 by Pridi Banomyong; central to the 1973 student uprising and the 1976 massacre."},"103":{"what":"Thailand's oldest university, founded in 1917, between Siam and Sam Yan.","why":"Leafy campus of elegant Thai-style buildings, plus the nearby Chulalongkorn University Centenary Park."},"104":{"what":"Elevated walkway and cycle path linking Lumphini and Benchakitti parks.","why":"A car-free route above the streets, joining two of the city's best green spaces."},"105":{"what":"Huge suburban shopping centre on Bangna-Trat Road.","why":"One of Thailand's biggest malls, with IKEA next door, a cinema, a hypermarket and family dining."},"106":{"what":"Thailand's first IKEA, opened in 2011 beside MEGA Bangna.","why":"Full-size store with showroom, market hall, self-serve warehouse and the Swedish food restaurant."},"107":{"what":"Long-running Central mall at the Ha Yaek Lat Phrao junction.","why":"One of Bangkok's pioneering malls, opened in 1983, with a hotel and convention centre attached."},"108":{"what":"Lanes off Nana lined with Middle Eastern restaurants and shisha cafes.","why":"Bangkok's best spot for shawarma, mezze and grilled meats, with Arabic signs and late-night bustle.","when":"Evenings and late at night, when the shisha cafes fill up."},"109":{"what":"Leafy street running from Phloen Chit Road down to Lumphini Park.","why":"A quieter side of downtown, lined with cafes, restaurants and hotels; a pleasant walk to the park."},"110":{"what":"Modern Thai tasting-menu restaurant by chef Thitid 'Ton' Tassanakajohn, Silom.","why":"Seasonal Thai produce reimagined in refined courses; named Asia's best restaurant in 2023.","when":"Book well ahead; tables go fast."},"111":{"what":"Modern German tasting-menu restaurant run by twin chefs Thomas and Mathias Sühring.","why":"Refined takes on German family recipes, served in a garden-wrapped 1970s villa; among Asia's top tables.","when":"Book well in advance."},"112":{"what":"Progressive Indian tasting-menu restaurant by chef Gaggan Anand, Sukhumvit 31.","why":"Playful, theatrical dining from a chef whose restaurants have repeatedly topped Asia's 50 Best list.","when":"Book the moment reservations open; the small counter fills fast."},"113":{"what":"Large IKEA store next to Central WestGate in Bang Yai, Nonthaburi.","why":"Thailand's second IKEA, with full showroom, warehouse and restaurant for western Bangkok."},"114":{"what":"Compact city-centre IKEA on the third floor of EmSphere, Phrom Phong.","why":"IKEA's first city-format store in Southeast Asia; its restaurant overlooks Benchasiri Park."},"115":{"what":"Large private international hospital off Sukhumvit Soi 3, near Nana.","why":"One of Asia's best-known hospitals for international patients, with English-speaking staff and many specialist centres.","when":"Emergency department open 24 hours."},"116":{"what":"Flagship hospital of the Bangkok Hospital group, off New Phetchaburi Road.","why":"Headquarters of Thailand's largest private hospital group, with specialist heart, brain and cancer centres.","when":"Emergency department open 24 hours."},"117":{"what":"Private hospital on Sukhumvit Soi 49, between Phrom Phong and Thonglor.","why":"Popular with expat families, with a dedicated children's hospital and international patient services.","when":"Emergency department open 24 hours."},"118":{"what":"Private hospital on Srinakarin Road in eastern Bangkok.","why":"The Samitivej group's eastern branch, serving Bangkok's eastern suburbs, including many international families.","when":"Emergency department open 24 hours."},"119":{"what":"Large private hospital on Rama IV Road, near QSNCC and Khlong Toei.","why":"Opened in 2020 with a wide range of specialists in one modern building.","when":"Emergency department open 24 hours."},"120":{"what":"Private hospital on Convent Road, just off Silom.","why":"One of Bangkok's oldest private hospitals, founded in 1898 as the Bangkok Nursing Home.","when":"Emergency department open 24 hours."},"121":{"what":"Private hospital on Phahon Yothin Road, near Ari and Saphan Khwai.","why":"Main hospital of the Phyathai group, with international patient services.","when":"Emergency department open 24 hours."},"122":{"what":"Private hospital on Rama IX Road.","why":"Long-established general hospital close to the Rama 9 business district.","when":"Emergency department open 24 hours."},"123":{"what":"Private international hospital on Lat Phrao Soi 111.","why":"Known for orthopaedics and for treating many patients from abroad.","when":"Emergency department open 24 hours."},"124":{"what":"Thai Red Cross teaching hospital of Chulalongkorn University, by Lumphini Park.","why":"One of Thailand's largest public hospitals, with leading specialists and research.","when":"24-hour emergency department; expect long queues for outpatients."},"125":{"what":"Thailand's oldest hospital, on the Thonburi riverside by Wang Lang.","why":"Founded in 1888; Mahidol University's huge teaching hospital, also home to medical museums.","when":"24-hour emergency department; expect long queues for outpatients."},"126":{"what":"Mahidol University teaching hospital on Rama VI Road, near Victory Monument.","why":"One of Bangkok's leading public hospitals for complex and specialist care.","when":"24-hour emergency department; expect long queues for outpatients."},"127":{"what":"Open-air community mall on Thong Lo Soi 17, opened 2016.","why":"Stepped terraces of cafés, bakeries and restaurants, including Roast and Roots coffee; a favourite Thonglor hangout.","when":"Weekend brunch, or early evening on the terraces."},"128":{"what":"Three-storey community mall on Sala Daeng Soi 1, opened 2020.","why":"Sister of the Thonglor original, with Roast, Roots coffee and about 20 food and drink spots near BTS Sala Daeng.","when":"Lunch or after work; pet-friendly."},"129":{"what":"Low, semi-outdoor community mall at Sindhorn Village on Lang Suan Road.","why":"Upscale restaurants and bars around a landscaped park shared with the Kempinski and Kimpton hotels; 'velaa' means time.","when":"Dinner; several restaurants need booking ahead."},"130":{"what":"Riverside luxury hotel on Charoen Krung Road, opened 2020.","why":"Ranked No. 2 in The World's 50 Best Hotels 2025, with gardens, art and acclaimed restaurants.","when":"Drinks or dinner by the river; book restaurants ahead."},"131":{"what":"Riverside luxury hotel next to the Four Seasons, opened 2020.","why":"Every room faces the Chao Phraya; No. 1 in The World's 50 Best Hotels 2024 and No. 3 in 2025.","when":"Dinner at its restaurant Côte; book well ahead."},"132":{"what":"Riverside luxury hotel on the Thonburi bank, opened 1998.","why":"Every room has river views, and its own boats shuttle guests across from Sathorn Pier.","when":"Afternoon tea in the lobby, or sunset on the riverside terrace."},"133":{"what":"Large riverside hotel beside BTS Saphan Taksin and Sathorn Pier.","why":"A long-standing riverside landmark with gardens, pools and wide river views.","when":"Riverside dinner, or a drink before a boat trip."},"134":{"what":"Luxury hotel in a striking tower on Ploenchit Road, opened 2019.","why":"The tower's shape echoes the Thai wai greeting; Lennon's vinyl bar sits near the top.","when":"Evening drinks; near BTS Phloen Chit."},"135":{"what":"Classic luxury hotel on South Sathorn Road, opened 1991.","why":"Calm courtyards and lotus ponds inspired by the old Sukhothai kingdom; Celadon serves refined Thai food.","when":"Afternoon tea or a quiet Thai dinner."},"136":{"what":"Resort-style luxury hotel tucked behind Siam Paragon.","why":"Tropical pool gardens in the middle of Siam, and Sra Bua by Kiin Kiin for modern Thai cooking.","when":"Lunch or dinner after shopping around Siam."},"137":{"what":"Riverside boutique hotel in Dusit, designed by Bill Bensley, opened 2012.","why":"Art deco villas, antiques and its own Muay Thai ring, far from the downtown bustle.","when":"An evening by the river; arrive by the hotel's boat."},"138":{"what":"Luxury hotel in the Central Embassy tower on Ploenchit Road.","why":"Penthouse Bar and Grill on the top floors, with sweeping city views.","when":"Evening drinks; near BTS Phloen Chit."},"139":{"what":"Landmark hotel reborn at Dusit Central Park, opposite Lumphini Park.","why":"The 1970 original was Bangkok's first high-rise luxury hotel; the new one reopened in September 2024.","when":"Lunch, then the public Roof Park above the mall."},"140":{"what":"Luxury hotel on Ratchadamri Road, next to BTS Ratchadamri.","why":"Views over the Royal Bangkok Sports Club racecourse; known for afternoon tea and its bar.","when":"Afternoon tea or sunset drinks."},"141":{"what":"Luxury hotel in the Magnolias Ratchadamri tower, opened 2018.","why":"Peacock Alley afternoon tea and views over the Royal Bangkok Sports Club.","when":"Afternoon tea or dinner; near BTS Ratchadamri and Chit Lom."},"142":{"what":"Fantasy-themed bar by designer Ashley Sutton, now on Sukhumvit Soi 39.","why":"A dark fairy-tale interior of iron, lanterns and jars of 'fairy dust', with live music.","when":"Late evening; it moved here from Thonglor in 2023."},"143":{"what":"Small vinyl and cocktail bar between Thonglor Soi 20 and Ekkamai Soi 21.","why":"DJs spin records in the house that once held the Sugar Ray bar; a short, careful cocktail list.","when":"Late evening; check it's still open, as some listings say it has closed."},"144":{"what":"Speakeasy in a former bank vault under Novotel Fenix on Silom Road.","why":"Ashley Sutton's 1930s Shanghai fantasy, with live jazz and performers on swings.","when":"Late evening; check it's still open, as listings disagree."},"145":{"what":"Cocktail bar and restaurant on Convent Road, Silom.","why":"On Asia's 50 Best Bars every year since 2016, with the 2025 Legend of the List award.","when":"Pre-dinner cocktails or a late drink."},"146":{"what":"Cocktail bar on Sukhumvit Soi 26.","why":"No. 4 in Asia's 50 Best Bars 2025, the top-ranked bar in Thailand that year.","when":"Evening; arrive early or book."},"147":{"what":"Cocktail bar on the top floors of a Chinatown shophouse.","why":"The 120-year-old building was once an opium den; a new entry on Asia's 50 Best Bars 2025.","when":"After dinner in Yaowarat."},"148":{"what":"Cocktail bar in a 136-year-old mansion on North Sathorn Road.","why":"New on Asia's 50 Best Bars 2025, with inventive drinks drawing on local history.","when":"Evening drinks."},"149":{"what":"Temple in Bang Khun Phrom with a 32-metre standing Buddha, Luang Pho To.","why":"One of Bangkok's tallest Buddha images, built 1867-1927; visitors climb steps to offer gold leaf.","when":"Mornings; its annual temple fair is held in early March (check dates)."},"150":{"what":"Muay Thai stadium on Ram Intra Road, run by the Royal Thai Army.","why":"With Rajadamnern, one of the two great Muay Thai stadiums; it moved here from Rama IV in 2014.","when":"Fight nights, often Tuesday, Friday and Saturday; check the schedule."},"151":{"what":"Japanese-style onsen on the fifth floor of Grande Centre Point, Sukhumvit 55.","why":"Five baths with mineral powder from Gero, Japan, plus saunas and massage.","when":"An evening soak, then a massage."},"152":{"what":"Japanese-style onsen and spa by Rama IV Road, Khlong Toei.","why":"Wooden bathhouse with separate men's and women's baths, saunas and massage.","when":"Weekday evenings are calmer."},"153":{"what":"Late-night market by MRT Huai Khwang.","why":"Spicy Isan food, seafood and snacks into the small hours, used more by locals than tourists.","when":"After 9 pm, until very late."},"154":{"what":"Long-running fresh market, now on Chula Soi 32.","why":"Fresh produce and cheap food stalls, near the Banthat Thong food street.","when":"Lunch or early dinner."},"155":{"what":"Night market around the fairy-tale castle of the old Dan Neramit amusement park.","why":"Street food, bars and shops beside a landmark castle, run by the Jodd Fairs team.","when":"Evenings, especially weekends."}};
